    }>;

    const usage = new Map<string, KeyWindowUsage>();
    for (const r of rows) {
      usage.set(usageCacheKey(r.platform, r.model_id, r.key_id), {
        rpm: r.rpm_used, rpd: r.rpd_used, tpm: r.tpm_used, tpd: r.tpd_used,
