keysRouter.post('/', async (req: Request, res: Response) => {
  const parsed = addKeySchema.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: { message: parsed.error.issues[0].message } });
    return;
  }

  const { platform, key, label, proxyUrl } = parsed.data;
  const provider = resolveProvider(platform as Platform);
  if (!provider) {
    res.status(400).json({ error: { message: `Unsupported platform: ${platform}` } });
    return;
  }

  const trimmedKey = key?.trim() ?? '';
  if (!trimmedKey && !provider.keyless) {
    res.status(400).json({ error: { message: 'API key is required for this provider' } });
    return;
  }

  const effectiveKey = trimmedKey || 'no-key';
  const db = getDb();
  const { encrypted, iv, auth_tag: authTag } = encrypt(effectiveKey);
  const encryptedProxy = proxyUrl ? encryptProxyUrl(proxyUrl) : { encrypted: null, iv: null, authTag: null };

  const result = db.prepare(`
    INSERT INTO api_keys (platform, label, encrypted_key, iv, auth_tag, status, enabled, proxy_url_encrypted, proxy_url_iv, proxy_url_auth_tag)
    VALUES (?, ?, ?, ?, ?, 'unknown', 1, ?, ?, ?)
  `).run(
    platform,
    label?.trim() || null,
    encrypted,
    iv,
    authTag,
    encryptedProxy.encrypted,
    encryptedProxy.iv,
    encryptedProxy.authTag,
  );

  const keyId = Number(result.lastInsertRowid);
  const verifyResult = await verifyCredentials(platform as Platform, effectiveKey, keyId);

  res.json({
    success: true,
    id: keyId,
    status: verifyResult.status,
    message: noModelsNotice(platform),
  });
});

